INSERT INTO collection_pages VALUES('78768d228e477642298a972658ba7ed76e398356c2602c15719730db8dfd3826','c999c0bb67df284e5dff1164f0658754fb4ec0421c7d5c35fbf780c28a56f3be','{"hasNext":false,"items":[{"author":{"account":null,"email":"=","name":"="},"authoredDate":"2026-05-31T17:58:56Z","committedDate":"2026-05-31T17:59:28Z","committer":{"account":null,"email":"=","name":"="},"observedAt":"2026-10-08T22:43:50.757Z","repositoryId":1216433023,"sha":"769b840d3bc695426fad815c42ee101260b48f04"},{"author":{"account":null,"email":"=","name":"="},"authoredDate":"2026-04-18T13:14:21Z","committedDate":"2026-04-18T13:14:21Z","committer":{"account":null,"email":"=","name":"="},"observedAt":"2026-10-08T22:43:50.757Z","repositoryId":1216433023,"sha":"de4b9704db1af183dbddf641023d83099bb5d092"}],"observedAt":"2026-10-08T22:43:50.757Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/Muroz/micro-commerce/commits/769b840d3bc695426fad815c42ee101260b48f04/comments","commit":{"author":{"date":"2026-05-31T17:58:56Z","email":"=","name":"="},"comment_count":0,"committer":{"date":"2026-05-31T17:59:28Z","email":"=","name":"="},"message":"feat: domain API pattern with manifest-driven dynamic remotes\n\nReplaces hardcoded localhost remote URLs with a runtime manifest the shell\nfetches once per session, with a build-time fallback manifest baked in for\nmanifest-service outages. Each MFE now exposes its domain API as a federated\nmodule (cart/cartApi, products/productsApi, checkout/checkoutApi) so consumers\nimport behavior across MFE boundaries instead of pulling singleton packages\ndirectly. Adds per-remote RemoteErrorBoundary so a failing remote degrades\nlocally instead of taking down the shell, consolidates federated module types\ninto @mfe/remotes-types, and wires a check-contracts task that tsc''s every\napp on PRs touching any *-api package.","tree":{"sha":"b1381487841ea3799b213197c31e626bdcadb0ba","url":"https://api.github.com/repos/Muroz/micro-commerce/git/trees/b138148